INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001750150','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001750150","revision":1,"targetId":"80000000-0000-4000-8000-000000017515","prompt":"Für die Tomatensoße brät er fein gewürfelte ___ glasig an.","instruction":{"en":"Choose the option that completes the German sentence correctly.","de":"Wähle die Option, die den deutschen Satz richtig ergänzt."},"hint":{"en":"This vegetable is commonly sautéed until translucent.","de":"Dieses Gemüse wird häufig glasig angebraten."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Nudeln"},{"id":"1","text":"Oliven"},{"id":"2","text":"Zwiebeln"},{"id":"3","text":"Bohnen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Finely diced onions are often sautéed until translucent.","de":"Fein gewürfelte Zwiebeln werden häufig glasig angebraten."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Für die Tomatensoße brät er fein gewürfelte Zwiebeln glasig an.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2805 (74d4af17416b7b1af42a9470b8d34c99fbeb6147c8a1c32aff863c9f93ade57d), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
