INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001750160','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001750160","revision":1,"targetId":"80000000-0000-4000-8000-000000017516","prompt":"Zwischen zwei Maschinen bleibt ein schmaler ___, der zur Reinigung zugänglich sein muss.","instruction":{"en":"Choose the option that completes the German sentence correctly.","de":"Wähle die Option, die den deutschen Satz richtig ergänzt."},"hint":{"en":"The space lies between the machines.","de":"Der freie Bereich liegt zwischen den Maschinen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Wohnraum"},{"id":"1","text":"Stauraum"},{"id":"2","text":"Zwischenraum"},{"id":"3","text":"Innenraum"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Zwischenraum names the space separating the machines.","de":"Zwischenraum bezeichnet den freien Bereich zwischen den Maschinen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Zwischen zwei Maschinen bleibt ein schmaler Zwischenraum, der zur Reinigung zugänglich sein muss.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2806 (4b4fa563439ee4b3ed6864fdfb08606fd2b8a9b2cb3ae50701b979c634665b34), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
